func TestExtraBoundaries(t *testing.T) {
	cases := []struct {
		n    int
		want string
	}{
		{99, "99 bottles of beer on the wall, 99 bottles of beer.\nTake one down and pass it around, 98 bottles of beer on the wall.\n"},
		{10, "10 bottles of beer on the wall, 10 bottles of beer.\nTake one down and pass it around, 9 bottles of beer on the wall.\n"},
		{2, "2 bottles of beer on the wall, 2 bottles of beer.\nTake one down and pass it around, 1 bottle of beer on the wall.\n"},
		{1, "1 bottle of beer on the wall, 1 bottle of beer.\nTake it down and pass it around, no more bottles of beer on the wall.\n"},
		{0, "No more bottles of beer on the wall, no more bottles of beer.\nGo to the store and buy some more, 99 bottles of beer on the wall.\n"},
	}
	for _, tc := range cases {
		got, err := Verse(tc.n)
		if err != nil {
			t.Errorf("Verse(%d) unexpected error: %v", tc.n, err)
			continue
		}
		if got != tc.want {
			t.Errorf("Verse(%d)\n got:%q\nwant:%q", tc.n, got, tc.want)
		}
	}

	for _, n := range []int{-1, 100, 104} {
		if _, err := Verse(n); err == nil {
			t.Errorf("Verse(%d) expected an error", n)
		}
	}

	if got, err := Verses(0, 0); err != nil || got != cases[4].want+"\n" {
		t.Errorf("Verses(0,0)\n got:%q, err:%v\nwant:%q", got, err, cases[4].want+"\n")
	}
	if got, err := Verses(99, 99); err != nil || got != cases[0].want+"\n" {
		t.Errorf("Verses(99,99)\n got:%q, err:%v\nwant:%q", got, err, cases[0].want+"\n")
	}
	for _, bounds := range [][2]int{{0, 1}, {-1, -1}, {100, 99}, {99, -20}} {
		if _, err := Verses(bounds[0], bounds[1]); err == nil {
			t.Errorf("Verses(%d,%d) expected an error", bounds[0], bounds[1])
		}
	}
}

func TestFullSongCheck(t *testing.T) {
	song := Song()
	if !strings.HasPrefix(song, "99 bottles of beer on the wall, 99 bottles of beer.\n") {
		t.Errorf("song has unexpected opening: %q", song[:min(80, len(song))])
	}
	if !strings.HasSuffix(song, "Go to the store and buy some more, 99 bottles of beer on the wall.\n\n") {
		t.Errorf("song has unexpected ending: %q", song[max(0, len(song)-90):])
	}
	if strings.Contains(song, "0 bottles") || strings.Contains(song, "1 bottles") {
		t.Error("song contains an incorrectly pluralized bottle count")
	}
	nonEmpty := 0
	for _, line := range strings.Split(song, "\n") {
		if line != "" {
			nonEmpty++
		}
	}
	if nonEmpty != 200 {
		t.Errorf("song has %d non-empty lines, want 200", nonEmpty)
	}
}

